<template>
  <div class="wrapper" :class="{ progress: watched }">
    <div class="video-player">
      
      <!-- iFrame for all videos -->
      <iframe
        ref="videoFrame"
        :src="getEnhancedVideoUrl()"
        width="100%"
        height="100%"
        frameborder="0"
        allowfullscreen
      ></iframe>
    </div>
  </div>
</template>

<script>
export default {
  name: "VideoPlayer",
  props: {
    video: {
      type: Object,
      required: true,
    },
    index: {
      type: Number,
      required: true
    }
  },
  data() {
    return {
      fullscreen: false,
      watched: false,
      videoEnded: false,
      isPlaying: false,
      progressPercentage: 0,
      progressTimer: null,
      completionTimer: null,
      playStartTime: null,
      totalPlayedTime: 0,
      lastUpdateTime: null,
      isManuallyStopped: true,
      iframeClickDetected: false
    }
  },
  computed: {
    videoLength() {
      return (this.video.durationSeconds || 60) * 1000;
    },
    videoSource() {
      return this.video.play || '';
    },
    isYouTube() {
      return this.videoSource.includes('youtube.com') || this.videoSource.includes('youtu.be');
    },
    isVimeo() {
      return this.videoSource.includes('vimeo.com');
    }
  },
  watch: {
    isPlaying(newValue) {
      if (newValue) {
        this.startProgressTracking();
        this.enterFullscreen();
        this.onVideoStartPlaying();
      } else {
        this.stopProgressTracking();
        if (this.isManuallyStopped) {
          this.exitFullscreen();
        }
      }
    }
  },
  mounted() {
    // Add event listener for messages from iframe (YouTube, Vimeo API)
    window.addEventListener('message', this.handleIframeMessage);
    
    // Add fullscreen change event listeners
    document.addEventListener('fullscreenchange', this.onFullscreenChange);
    document.addEventListener('webkitfullscreenchange', this.onFullscreenChange);
    document.addEventListener('mozfullscreenchange', this.onFullscreenChange);
    document.addEventListener('MSFullscreenChange', this.onFullscreenChange);

    // Add visibility change listener to pause when tab is not visible
    document.addEventListener('visibilitychange', this.handleVisibilityChange);
    
    // Add a global click handler to detect clicks anywhere in the document
    document.addEventListener('click', this.checkIfIframeWasClicked);
    
    // Create a MutationObserver to detect play button click inside iframe
    this.setupMutationObserver();
  },
  beforeUnmount() {
    // Cleanup all timers and listeners
    this.stopProgressTracking();
    clearTimeout(this.completionTimer);
    window.removeEventListener('message', this.handleIframeMessage);
    document.removeEventListener('fullscreenchange', this.onFullscreenChange);
    document.removeEventListener('webkitfullscreenchange', this.onFullscreenChange);
    document.removeEventListener('mozfullscreenchange', this.onFullscreenChange);
    document.removeEventListener('MSFullscreenChange', this.onFullscreenChange);
    document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    document.removeEventListener('click', this.checkIfIframeWasClicked);
    
    // Disconnect mutation observer if exists
    if (this.observer) {
      this.observer.disconnect();
    }
  },
  methods: {
    // Get enhanced video URL with API parameters
    getEnhancedVideoUrl() {
      let url = this.videoSource;
      
      if (this.isYouTube) {
        // Add YouTube API parameters
        const separator = url.includes('?') ? '&' : '?';
        url = `${url}${separator}enablejsapi=1&origin=${encodeURIComponent(window.location.origin)}`;
      } else if (this.isVimeo) {
        // Add Vimeo API parameters
        const separator = url.includes('?') ? '&' : '?';
        url = `${url}${separator}api=1`;
      }
      
      return url;
    },
    
    // Handle iframe click detection
    handleIframeClick() {
      console.log("Transparent overlay clicked, starting playback");
      this.iframeClickDetected = true;
      this.startPlayback();
    },
    
    // Check if a click was on or within the iframe
    checkIfIframeWasClicked(event) {
      const iframe = this.$refs.videoFrame;
      if (!iframe) return;
      
      // Get iframe position
      const rect = iframe.getBoundingClientRect();
      
      // Check if click was inside iframe area
      if (
        event.clientX >= rect.left &&
        event.clientX <= rect.right &&
        event.clientY >= rect.top &&
        event.clientY <= rect.bottom
      ) {
        // Click was inside iframe area
        if (!this.isPlaying) {
          console.log("Click detected inside iframe bounds");
          
          // Small delay to allow internal iframe click to process first
          setTimeout(() => {
            // Only trigger playback if we're not already playing
            if (!this.isPlaying) {
              this.startPlayback();
            }
          }, 100);
        }
      }
    },
    
    // Setup mutation observer to detect DOM changes in iframe (may help detect play state)
    setupMutationObserver() {
      try {
        // Create a MutationObserver
        this.observer = new MutationObserver((mutations) => {
          // Check if any mutations might indicate video play state changed
          mutations.forEach((mutation) => {
            if (
              mutation.type === 'childList' || 
              mutation.type === 'attributes' ||
              mutation.type === 'characterData'
            ) {
              // Check if we're not already playing and video has started
              if (!this.isPlaying && this.detectVideoPlayingFromDOM()) {
                console.log("DOM mutation detected play state change");
                this.isPlaying = true;
              }
            }
          });
        });
        
        // Start observing
        this.observer.observe(document.body, {
          childList: true,
          subtree: true,
          attributes: true,
          characterData: true
        });
      } catch (e) {
        console.error("Error setting up MutationObserver:", e);
      }
    },
    
    // Try to detect if video is playing based on DOM elements
    detectVideoPlayingFromDOM() {
      // This is a simplified example - the actual implementation
      // would depend on your specific video player/iframe
      const iframe = this.$refs.videoFrame;
      if (!iframe) return false;
      
      try {
        // For YouTube, try to find play/pause button state
        // Note: This may not work due to same-origin policy
        const iframeDoc = iframe.contentDocument || iframe.contentWindow.document;
        const playButton = iframeDoc.querySelector('.ytp-play-button');
        
        if (playButton) {
          // Check if aria-label indicates playing state
          return playButton.getAttribute('aria-label')?.includes('Pause');
        }
      } catch (e) {
        // Cross-origin error expected - will rely on other methods
      }
      
      return false;
    },
    
    // Handle messages from iframe (YouTube/Vimeo API)
    handleIframeMessage(event) {
      // YouTube API messages
      if (this.isYouTube) {
        try {
          const data = event.data;
          if (typeof data === 'object' && data !== null) {
            // YouTube API sends state changes
            if (data.event === 'onStateChange') {
              if (data.info === 1) {
                // YouTube is playing (state = 1)
                if (!this.isPlaying) {
                  console.log("YouTube API reported video playing");
                  this.isPlaying = true;
                }
              } else if (data.info === 0 || data.info === 2) {
                // YouTube video ended (0) or paused (2)
                if (this.isPlaying) {
                  this.isPlaying = false;
                }
              }
            }
          }
        } catch (e) {
          console.error("Error processing YouTube message:", e);
        }
      }
      
      // Vimeo API messages
      if (this.isVimeo) {
        try {
          const data = typeof event.data === 'string' ? JSON.parse(event.data) : event.data;
          
          if (data.event === 'play') {
            if (!this.isPlaying) {
              console.log("Vimeo API reported video playing");
              this.isPlaying = true;
            }
          } else if (data.event === 'pause' || data.event === 'finish') {
            if (this.isPlaying) {
              this.isPlaying = false;
            }
          }
        } catch (e) {
          console.error("Error processing Vimeo message:", e);
        }
      }
    },
    
    // Custom function to run when video starts
    onVideoStartPlaying() {
      console.log("Video started playing - running custom function");
      // Add your custom logic here
      
      // Example: emit an event to parent component
      this.$emit('video-started', {
        videoId: this.video.id,
        timestamp: Date.now(),
        source: this.videoSource
      });
    },
    
    startPlayback() {
      if (this.videoEnded) {
        this.markAsWatched();
        return;
      }

      console.log("Starting video playback");
      
      // For YouTube/Vimeo, try to use their APIs
      if (this.isYouTube) {
        try {
          const iframe = this.$refs.videoFrame;
          iframe.contentWindow.postMessage(JSON.stringify({
            event: 'command',
            func: 'playVideo'
          }), '*');
        } catch (e) {
          console.error("Error controlling YouTube iframe:", e);
        }
      } else if (this.isVimeo) {
        try {
          const iframe = this.$refs.videoFrame;
          iframe.contentWindow.postMessage(JSON.stringify({
            method: 'play'
          }), '*');
        } catch (e) {
          console.error("Error controlling Vimeo iframe:", e);
        }
      }

      // Set our component state to playing
      this.isPlaying = true;
      this.isManuallyStopped = false;
      this.playStartTime = Date.now();
      this.lastUpdateTime = this.playStartTime;

      // Set video completion timer
      const remainingTime = this.videoLength - this.totalPlayedTime;
      if (remainingTime > 0) {
        this.completionTimer = setTimeout(() => {
          this.completeVideo();
        }, remainingTime);
      } else {
        this.completeVideo();
      }
    },

    pausePlayback() {
      // Send pause command to iframe if YouTube/Vimeo
      if (this.isYouTube) {
        try {
          const iframe = this.$refs.videoFrame;
          iframe.contentWindow.postMessage(JSON.stringify({
            event: 'command',
            func: 'pauseVideo'
          }), '*');
        } catch (e) {
          console.error("Error pausing YouTube iframe:", e);
        }
      } else if (this.isVimeo) {
        try {
          const iframe = this.$refs.videoFrame;
          iframe.contentWindow.postMessage(JSON.stringify({
            method: 'pause'
          }), '*');
        } catch (e) {
          console.error("Error pausing Vimeo iframe:", e);
        }
      }

      this.isPlaying = false;
      this.isManuallyStopped = true;
      clearTimeout(this.completionTimer);

      if (this.playStartTime) {
        this.totalPlayedTime += (Date.now() - this.playStartTime);
        this.playStartTime = null;
      }
    },

    startProgressTracking() {
      this.stopProgressTracking();
      this.progressTimer = setInterval(() => {
        if (!this.isPlaying) return;

        const now = Date.now();
        if (this.playStartTime) {
          const currentPlayedTime = this.totalPlayedTime + (now - this.playStartTime);
          this.progressPercentage = Math.min(100, (currentPlayedTime / this.videoLength) * 100);
          this.lastUpdateTime = now;
        }
      }, 250);
    },

    stopProgressTracking() {
      if (this.progressTimer) {
        clearInterval(this.progressTimer);
        this.progressTimer = null;
      }
    },

    completeVideo() {
      this.videoEnded = true;
      this.isPlaying = false;
      this.progressPercentage = 100;
      this.stopProgressTracking();
      this.exitFullscreen();
    },

    enterFullscreen() {
      try {
        const elem = this.$el;
        if (!this.fullscreen && elem) {
          if (elem.requestFullscreen) {
            elem.requestFullscreen();
          } else if (elem.webkitRequestFullscreen) {
            elem.webkitRequestFullscreen();
          } else if (elem.msRequestFullscreen) {
            elem.msRequestFullscreen();
          }
        }
      } catch (e) {
        console.error('Could not enter fullscreen mode:', e);
      }
    },

    exitFullscreen() {
      try {
        if (this.fullscreen && document.exitFullscreen) {
          document.exitFullscreen();
        } else if (document.webkitExitFullscreen) {
          document.webkitExitFullscreen();
        } else if (document.msExitFullscreen) {
          document.msExitFullscreen();
        }
      } catch (e) {
        console.error('Could not exit fullscreen mode:', e);
      }
    },

    onFullscreenChange() {
      const isFullscreen = !!document.fullscreenElement ||
        !!document.webkitFullscreenElement ||
        !!document.mozFullScreenElement ||
        !!document.msFullscreenElement;

      if (this.fullscreen && !isFullscreen && this.isPlaying) {
        this.pausePlayback();
      }

      this.fullscreen = isFullscreen;
    },

    handleVisibilityChange() {
      if (document.hidden && this.isPlaying) {
        this.pausePlayback();
      }
    },

    markAsWatched() {
      this.watched = true;
      this.$emit('video-watched', this.video);
    },

    resetPlayer() {
      this.videoEnded = false;
      this.isPlaying = false;
      this.progressPercentage = 0;
      this.totalPlayedTime = 0;
      this.playStartTime = null;
      this.lastUpdateTime = null;
      this.isManuallyStopped = true;
      this.stopProgressTracking();
      clearTimeout(this.completionTimer);
    }
  }
}
</script>

